(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function notas(){const m=$('#notasMain');if(!m)return;$$('.notaPdf',m).forEach(b=>b.remove());const modal=$('#notaPdfModal',m);if(modal)modal.remove();}
function installCard(){if(matchMedia('(display-mode: standalone)').matches||navigator.standalone===true)return;if($('#obrixInstallCompact'))return;const card=document.createElement('div');card.id='obrixInstallCompact';card.innerHTML='<button class="obrixInstallX" type="button" aria-label="Fechar">×</button><div class="obrixInstallText"><b>Instalar OBRIX</b><span>Use no navegador ou adicione à Tela de Início.</span></div><button class="obrixInstallBtn" type="button">Como instalar</button>';document.body.appendChild(card);$('.obrixInstallX',card).onclick=()=>{card.remove();sessionStorage.setItem('obrix-install-dismissed','1')};if(sessionStorage.getItem('obrix-install-dismissed')==='1'){card.remove();return}let deferred=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e},{once:true});$('.obrixInstallBtn',card).onclick=async()=>{if(deferred){deferred.prompt();await deferred.userChoice;deferred=null;return}const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);alert(ios?'No Safari: toque em Compartilhar e depois em “Adicionar à Tela de Início”. Você também pode continuar usando o OBRIX normalmente no navegador.':'No menu do navegador, escolha “Instalar aplicativo” ou “Adicionar à tela inicial”. Você também pode continuar usando o OBRIX normalmente no navegador.')};}
function apply(){notas();installCard()}
const css=document.createElement('style');css.textContent=`#obrixPrivacyBtn,.obrixPrivacyBar{display:none!important}#obrixInstallCompact{position:fixed;left:50%;bottom:72px;transform:translateX(-50%);z-index:99990;width:min(430px,calc(100% - 24px));display:flex;align-items:center;gap:9px;background:#fff;color:#0f172a;border:1px solid #dbe3ec;border-radius:14px;padding:9px 10px;box-shadow:0 10px 30px rgba(15,23,42,.18)}.obrixInstallText{min-width:0;flex:1}.obrixInstallText b{display:block;font-size:13px;line-height:1.1}.obrixInstallText span{display:block;font-size:10px;line-height:1.25;color:#64748b;margin-top:3px}.obrixInstallBtn{border:0;border-radius:9px;background:#0f172a;color:#fff;padding:9px 10px;font-size:11px;font-weight:900;white-space:nowrap}.obrixInstallX{order:3;width:29px;height:29px;border:0;border-radius:9px;background:#eef2f7;color:#334155;font-size:20px;line-height:1;padding:0}@media(min-width:760px){#obrixInstallCompact{bottom:18px}}@media(max-width:420px){.obrixInstallText span{max-width:170px}.obrixInstallBtn{padding:8px 9px}}html[data-theme="dark"] #obrixInstallCompact{background:#111827;color:#f8fafc;border-color:#334155}html[data-theme="dark"] .obrixInstallText span{color:#cbd5e1}html[data-theme="dark"] .obrixInstallX{background:#334155;color:#fff}html[data-theme="dark"] .obrixInstallBtn{background:#f8fafc;color:#0f172a}`;document.head.appendChild(css);
sessionStorage.removeItem('obrix-fin-hidden');
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(apply,450));else setTimeout(apply,450);
})();